// Tuples keep authored translations together: answer, cues, notes, and example.
// IDs persist in learner progress: keep existing rows in order; append new rows
// after the existing rows for that language and kind, including across groups.
const vocabularyCounts = {};
const grammarCounts = {};
function vocabulary(language, topic, rows) {
  return rows.map(([answer, en, es, noteEn, noteEs, target, exampleEn, exampleEs]) => {
    const number = vocabularyCounts[language] = (vocabularyCounts[language] ?? 0) + 1;
    return {
      id: `${language}-v-${String(number).padStart(2, '0')}`, language, kind: 'vocabulary', topic, level: 'A1',
      cue: { en, es }, answers: Array.isArray(answer) ? answer : [answer],
      note: { en: noteEn, es: noteEs }, example: { target, en: exampleEn, es: exampleEs },
    };
  });
}

function grammar(language, rows) {
  return rows.map(([topic, level, en, es, answer, noteEn, noteEs, target, exampleEn, exampleEs]) => {
    const number = grammarCounts[language] = (grammarCounts[language] ?? 0) + 1;
    return {
      id: `${language}-g-${String(number).padStart(2, '0')}`, language, kind: 'grammar', topic, level,
      cue: {
        en: en.includes('___') ? `${en} Write only the missing text.` : en,
        es: es.includes('___') ? `${es} Escribe solo el texto que falta.` : es,
      }, answers: Array.isArray(answer) ? answer : [answer],
      note: { en: noteEn, es: noteEs }, example: { target, en: exampleEn, es: exampleEs },
    };
  });
}

