  ...grammar('de', [
    ['Present: sein', 'A1', 'Fill with sein in the present: Ich ___ müde.', 'Completa con sein en presente: Ich ___ müde.', 'bin', 'Ich bin means I am.', 'Ich bin significa soy o estoy.', 'Ich bin müde.', 'I am tired.', 'Estoy cansado.'],
    ['Present: haben', 'A1', 'Fill with haben in the present: Du ___ ein Buch.', 'Completa con haben en presente: Du ___ ein Buch.', 'hast', 'Du hast means you have with one familiar person.', 'Du hast significa tienes con una persona de confianza.', 'Du hast ein Buch.', 'You have a book.', 'Tienes un libro.'],
    ['Present: regular verbs', 'A1', 'Fill with kommen in the present: Er ___ aus Berlin.', 'Completa con kommen en presente: Er ___ aus Berlin.', 'kommt', 'Er, sie, and es usually take -t in the present.', 'Er, sie y es suelen llevar -t en presente.', 'Er kommt aus Berlin.', 'He comes from Berlin.', 'Él es de Berlín.'],
    ['Present: wir', 'A1', 'Fill with wohnen in the present: Wir ___ hier.', 'Completa con wohnen en presente: Wir ___ hier.', 'wohnen', 'With wir, the present form usually matches the infinitive.', 'Con wir, la forma del presente suele coincidir con el infinitivo.', 'Wir wohnen hier.', 'We live here.', 'Vivimos aquí.'],
    ['Plural nouns', 'A1', 'Give the plural noun: ein Buch → zwei ___.', 'Escribe el sustantivo en plural: ein Buch → zwei ___.', 'Bücher', 'Learn the noun’s article and plural together: das Buch, die Bücher.', 'Aprende el artículo y el plural juntos: das Buch, die Bücher.', 'Ich habe zwei Bücher.', 'I have two books.', 'Tengo dos libros.'],
    ['Negation: kein', 'A1', 'Fill with the correct form of kein: Ich habe ___ Auto.', 'Completa con la forma correcta de kein: Ich habe ___ Auto.', 'kein', 'Kein negates an indefinite noun; Auto is neuter accusative here.', 'Kein niega un sustantivo indeterminado; Auto está en acusativo neutro.', 'Ich habe kein Auto.', 'I do not have a car.', 'No tengo coche.'],
    ['Accusative articles', 'A1', 'Use ein in the correct form: Ich kaufe ___ Apfel.', 'Usa ein en la forma correcta: Ich kaufe ___ Apfel.', 'einen', 'A masculine direct object takes einen in the accusative.', 'Un complemento directo masculino lleva einen en acusativo.', 'Ich kaufe einen Apfel.', 'I am buying an apple.', 'Compro una manzana.'],
    ['Dative articles', 'A2', 'Fill with the definite article: Ich fahre mit ___ Zug.', 'Completa con el artículo determinado: Ich fahre mit ___ Zug.', 'dem', 'Mit always takes the dative; der Zug becomes dem Zug.', 'Mit siempre lleva dativo; der Zug pasa a dem Zug.', 'Ich fahre mit dem Zug.', 'I am travelling by train.', 'Viajo en tren.'],
    ['Possessives', 'A1', 'Use mein in the correct form: Das ist ___ Buch.', 'Usa mein en la forma correcta: Das ist ___ Buch.', 'mein', 'Neuter nominative uses mein without an ending.', 'El nominativo neutro usa mein sin terminación.', 'Das ist mein Buch.', 'That is my book.', 'Ese es mi libro.'],
    ['Separable verbs', 'A2', 'Complete aufstehen with its separated prefix: Ich stehe um sieben Uhr ___.', 'Completa aufstehen con su prefijo separado: Ich stehe um sieben Uhr ___.', 'auf', 'In a main clause, the separable prefix goes at the end.', 'En una oración principal, el prefijo separable va al final.', 'Ich stehe um sieben Uhr auf.', 'I get up at seven.', 'Me levanto a las siete.'],
    ['Modal verbs', 'A1', 'Fill with müssen in the present: Ich ___ heute arbeiten.', 'Completa con müssen en presente: Ich ___ heute arbeiten.', 'muss', 'With a modal verb, the other verb stays in the infinitive at the end.', 'Con un verbo modal, el otro verbo queda en infinitivo al final.', 'Ich muss heute arbeiten.', 'I have to work today.', 'Tengo que trabajar hoy.'],
    ['Verb position', 'A1', 'Fill with fahren in the present: Morgen ___ ich nach Berlin.', 'Completa con fahren en presente: Morgen ___ ich nach Berlin.', 'fahre', 'The conjugated verb is in second position even when a time phrase comes first.', 'El verbo conjugado va en segunda posición aunque la frase empiece por un complemento temporal.', 'Morgen fahre ich nach Berlin.', 'Tomorrow, I am going to Berlin.', 'Mañana voy a Berlín.'],
    ['Perfect: haben', 'A2', 'Complete the perfect tense with haben: Ich ___ Brot gekauft.', 'Completa el perfecto con haben: Ich ___ Brot gekauft.', 'habe', 'Kaufen forms its perfect with haben + gekauft.', 'Kaufen forma el perfecto con haben + gekauft.', 'Ich habe Brot gekauft.', 'I bought bread.', 'He comprado pan.'],
    ['Perfect: sein', 'A2', 'Complete the perfect tense with sein: Ich ___ nach Hause gegangen.', 'Completa el perfecto con sein: Ich ___ nach Hause gegangen.', 'bin', 'Gehen expresses movement and forms its perfect with sein.', 'Gehen expresa desplazamiento y forma el perfecto con sein.', 'Ich bin nach Hause gegangen.', 'I went home.', 'He ido a casa.'],
    ['Past participles', 'A2', 'Use the past participle of kaufen: Sie hat ein Buch ___.', 'Usa el participio de kaufen: Sie hat ein Buch ___.', 'gekauft', 'Regular participles commonly use ge- + stem + -t.', 'Los participios regulares suelen usar ge- + raíz + -t.', 'Sie hat ein Buch gekauft.', 'She bought a book.', 'Ella ha comprado un libro.'],
    ['Subordinate clauses', 'A2', 'Put these words in order: weil / ich / bin / müde. Write the whole clause.', 'Ordena estas palabras: weil / ich / bin / müde. Escribe toda la subordinada.', 'weil ich müde bin', 'After weil, the conjugated verb goes at the end of the clause.', 'Después de weil, el verbo conjugado va al final de la subordinada.', 'Ich bleibe zu Hause, weil ich müde bin.', 'I am staying home because I am tired.', 'Me quedo en casa porque estoy cansado.'],
    ['Comparatives', 'A2', 'Use groß in the comparative: Berlin ist ___ als Bonn.', 'Usa groß en comparativo: Berlin ist ___ als Bonn.', ['größer', 'grösser'], 'Groß becomes größer (grösser in Switzerland); use als in the comparison.', 'Groß pasa a größer (grösser en Suiza); usa als en la comparación.', 'Berlin ist größer als Bonn.', 'Berlin is bigger than Bonn.', 'Berlín es más grande que Bonn.'],
    ['Location and dative', 'A2', 'Fill with the definite article for a location: Ich bin in ___ Küche. (die Küche)', 'Completa con el artículo determinado para una ubicación: Ich bin in ___ Küche. (die Küche)', 'der', 'In takes dative for location; feminine die becomes der.', 'In lleva dativo para una ubicación; el femenino die pasa a der.', 'Ich bin in der Küche.', 'I am in the kitchen.', 'Estoy en la cocina.'],
  ]),

